IDENTITY_KEYS = {
    "id",
    "name",
    "display_name",
    "description",
    "campaign_id",
    "campaign_name",
    "run_id",
    "created_at",
    "updated_at",
    "notes",
}

NON_CAUSAL_KEYS = {
    "save_previews",
    "preview_interval",
    "ui_group",
    "ui_order",
    "operator_comment",
}


def validate_parameter_space() -> None:
    names = [f"{item['stage']}.{item['name']}" for item in PARAMETERS]
    if len(names) != len(set(names)):
        raise ValueError("paramètres dupliqués")
    required_stages = {"qr", "prompt", "stage1", "stage2", "srmpgd", "evaluation", "runtime"}
    stages = {item["stage"] for item in PARAMETERS}
    if not required_stages <= stages:
        raise ValueError(f"étages absents: {sorted(required_stages - stages)}")
    for item in PARAMETERS:
        if not item.get("name") or not item.get("dtype") or not item.get("role"):
            raise ValueError(f"paramètre incomplet: {item}")


def _normalize(value: Any) -> Any:
    if isinstance(value, Mapping):
        output = {}
        for key in sorted(value):
            if key in IDENTITY_KEYS or key in NON_CAUSAL_KEYS:
                continue
            normalized = _normalize(value[key])
            if normalized is None:
                continue
            output[str(key)] = normalized
        return output
    if isinstance(value, (list, tuple)):
        return [_normalize(item) for item in value]
    if isinstance(value, float):
        return round(value, 12)
    return value


def effective_configuration(configuration: Mapping[str, Any]) -> dict[str, Any]:
    return _normalize(configuration)


def effective_signature(configuration: Mapping[str, Any]) -> str:
    return stable_hash(effective_configuration(configuration))


def validate_geometry(configuration: Mapping[str, Any]) -> list[str]:
    """Retourne les erreurs géométriques sans modifier la configuration."""
    errors: list[str] = []
    qr = configuration.get("qr") if isinstance(configuration.get("qr"), Mapping) else configuration
    version = int(qr.get("qr_version", 3))
    modules = 17 + 4 * version
    module_size = int(qr.get("module_size_px", 20))
    quiet_modules = int(qr.get("quiet_zone_modules", 4))
    canvas = int(qr.get("canvas_px", 736))
    core = modules * module_size
    required = core + 2 * quiet_modules * module_size
    if module_size <= 0:
        errors.append("module_size_px doit être positif")
    if quiet_modules < 4:
        errors.append("quiet_zone_modules doit être >= 4")
    if required > canvas:
        errors.append(
            f"canvas insuffisant: requis={required}, canvas={canvas}, core={core}"
        )
    # Le VAE SD1.x attend généralement des dimensions multiples de 8.
    if canvas % 8:
        errors.append("canvas_px doit être multiple de 8")
    return errors


validate_parameter_space()
